profile={...profile,careerGoal:profile.careerGoal??profile.goal??'',careerInterests:profile.careerInterests??profile.interests??'',socialGoal:profile.socialGoal||'',socialInterests:profile.socialInterests??(profile.interests||'').split(',').filter(x=>/film|music|culture|wellness|sport/i.test(x)).join(', '),graduationYear:profile.graduationYear||'',ageBand:profile.ageBand||'',careerDocuments:profile.careerDocuments||{},careerLinkedInURL:profile.careerLinkedInURL||''};
