function uiIcon(name,cls=''){const paths={spark:'M12 2l2.6 6.7L21 12l-6.4 3.3L12 22l-2.6-6.7L3 12l6.4-3.3L12 2z',calendar:'M7 2v4m10-4v4M3 10h18M4 4h16v17H4z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0zM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3m20 0v-3a4 4 0 0 0-3-3.9M13 5a4 4 0 1 1-8 0 4 4 0 0 1 8 0m4-3a4 4 0 0 1 0 8',building:'M3 22V8l9-5 9 5v14M2 22h20M7 10v3m5-3v3m5-3v3M7 16v3m10-3v3m-7 3v-6h4v6',briefcase:'M8 6V3h8v3M3 7h18v14H3zM3 12a20 20 0 0 0 18 0M10 12h4v4h-4z',check:'M9 12l2 2 4-5M12 2l8 3v6c0 6-8 11-8 11S4 17 4 11V5l8-3z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',cap:'M2 9l10-6 10 6-10 6L2 9zm4 3v6c4 3 8 3 12 0v-6m4-3v9'};return `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.spark}"/></svg>`}
function options(items,value){return items.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}
