const art=`<svg class="heroart" viewBox="0 0 600 350" fill="none" aria-hidden="true"><circle cx="388" cy="185" r="165" stroke="#ddd6c4"/><circle cx="388" cy="185" r="128" stroke="#ddd6c4"/><circle cx="388" cy="185" r="91" stroke="#ddd6c4"/><path d="M80 313H589" stroke="#c9c3af"/><ellipse cx="365" cy="307" rx="197" ry="19" fill="#e6dfcc"/><path d="M205 303V193H480V303" fill="#d4b79a" stroke="#9f7f68"/><path d="M195 193L344 144L490 193H195Z" fill="#aa6b59" stroke="#8e574b"/><path d="M234 303V212H455V303" fill="#e7d6b6" stroke="#aa8c6b"/><path d="M300 303V210H386V303" fill="#b18b68"/><path d="M316 303V248A27 27 0 0 1 370 248V303" fill="#766d55"/><path d="M309 206V119H379V206" fill="#e1c5a2" stroke="#a78665"/><path d="M303 119L345 80L385 119Z" fill="#a65c4b" stroke="#8a5449"/><path d="M336 82V62H353V82" fill="#d5b28a" stroke="#987b61"/><path d="M344 62V42" stroke="#997d62"/><path d="M345 43H368L345 54" fill="#8b252b"/><circle cx="344" cy="154" r="17" fill="#f2e9cf" stroke="#a18a6d"/><path d="M344 142V154L353 160" stroke="#967f61" stroke-width="2"/><path d="M254 231H272V265H254zM414 231H431V265H414zM224 231H234V265H224zM455 231H466V265H455z" fill="#7a806d"/><path d="M275 300V216M407 300V216" stroke="#bca681" stroke-width="7"/><path d="M290 310H398M283 316H406" stroke="#b8a381" stroke-width="5"/><path d="M152 310C164 252 161 208 148 161M148 161C110 158 98 178 100 193C123 187 139 176 148 161ZM148 161C168 136 191 136 204 151C183 154 166 157 148 161ZM148 161C116 135 104 142 95 156C115 157 134 159 148 161ZM148 161C160 126 153 115 137 112C138 134 142 149 148 161Z" fill="#8d9672" stroke="#7a8564"/><path d="M528 311C521 272 522 236 533 197M533 197C557 177 577 185 582 198C561 202 546 201 533 197ZM533 197C516 177 493 180 485 192C501 198 516 199 533 197ZM533 197C543 168 539 153 526 151C524 169 528 185 533 197Z" fill="#949c77" stroke="#7a8564"/><g transform="translate(433 56) rotate(9)"><rect width="101" height="57" rx="9" fill="#fffdf5" stroke="#e1d8c4"/><rect x="11" y="12" width="29" height="30" rx="6" fill="#f5e6dd"/><path d="M20 22h11m-11 5h11m-8-9v5m6-5v5" stroke="#9f4947"/><text x="48" y="24" fill="#757c65" font-family="sans-serif" font-size="7">ON YOUR RADAR</text><text x="48" y="37" fill="#31382c" font-family="sans-serif" font-size="10">Something good.</text></g><circle cx="235" cy="105" r="6" fill="#d5af59"/><path d="M489 245l6-10 6 10-6 10z" fill="#d2ad62"/></svg>`;
function score(e){const personal=preferenceScore(e,profile),type=eventPrimaryType(e);let value=personal;if(eventCategory(e)==='career'){if(['Info sessions','Networking & company visits','Applications & resumes','Interview practice','Career advising','Skills workshops','Hackathons'].includes(type))value+=5;if(type==='Research seminars'&&!personal)value-=12;}if(Date.parse(e.start)<now()-7*86400000)value-=30;if(/check-in/i.test(e.title))value-=25;if(e.eligibility==='Open to the public')value+=3;return value}
function why(e){if(aiPicks.key===recommendationKey()&&aiPicks.matchTypes?.[e.id]==='discovery')return 'Another eligible event in your selected dates. Explore a different direction.';if(aiPicks.state==='ai'&&aiPicks.key===recommendationKey()&&aiPicks.reasons[e.id])return aiPicks.reasons[e.id];const matches=preferenceMatches(e,profile);return matches.length?'Matches your interest in '+matches.slice(0,3).map(t=>t==='ai'?'AI':t).join(', ')+'.':'Explore this event and add preferences for a closer match.';}
function avatarMarkup(){const src=profile.avatarDataURL||(profile.demoProfile&&profile.name==='Jacqueline'?'/assets/jacqueline-avatar.jpg':'');return src?`<img src="${esc(src)}" alt="${esc(profile.name||'Your profile')}" referrerpolicy="no-referrer">`:esc((profile.name||'U').slice(0,1).toUpperCase())}
function renderAccount(){const menu=$('#accountMenu');$('#profileTop .avatar').innerHTML=avatarMarkup();$('#profileTop .account-label').textContent=profile.name||'Account';$('#profileTop').setAttribute('aria-expanded',String(accountOpen));menu.hidden=!accountOpen;menu.innerHTML=`<div class="account-summary"><span class="avatar">${avatarMarkup()}</span><div><strong>${esc(profile.name||'Your account')}</strong><small>${profile.demoProfile?'Demo profile · editable':'Saved in this browser'}</small></div></div><button role="menuitem" data-page="preferences">My preferences <span>↗</span></button><button role="menuitem" data-page="login">Account & calendar <span>↗</span></button>`;menu.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));}

function visible(){return events.filter(e=>!hidden.includes(e.id)&&eligibilityDecision(e,profile).eligible&&Date.parse(e.start)>=now()&&(e.end?Date.parse(e.end):Date.parse(e.start)+(e.allDay?86400000:7200000))>now())}
function matches(e,q){return (e.title+' '+e.host+' '+e.description+' '+e.source).toLowerCase().includes(q.toLowerCase())}
function fallbackImage(){return '/assets/fight-on-campus.jpg'}
function audienceMarkup(e,recommended=false){const d=eligibilityDecision(e,profile),proof=sourceEvidence(e);return `<div class="event-audience"><span class="organizer-kind" title="Organizer type; not an identity verification badge">${uiIcon(['Student organization','Student government','Faith community'].includes(organizerKind(e))?'people':['Employer','External brand / company'].includes(organizerKind(e))?'briefcase':'building')}${esc(organizerKind(e)==='Organizer unverified'?'Organizer type unconfirmed':organizerKind(e))}</span>${audienceBadges(e,profile).map(b=>`<span>${esc(b)}</span>`).join('')}${proof?`<span class="source-proof" title="${esc(proof.detail)}">${uiIcon('check')}${esc(proof.label)}</span>`:''}</div>${recommended?`<div class="eligibility-fit">${uiIcon('check')}Announced eligibility matches your profile</div>`:d.status==='ineligible'||d.status==='not-targeted'||d.status==='closed'?`<div class="eligibility-warning">Not recommended for your saved student details</div>`:d.status==='unknown'?'<div class="eligibility-pending">Not recommended until eligibility is confirmed</div>':''}`}
function card(e,recommended=false){return `<button class="card ${e.restricted?'restricted':''}" data-event="${esc(e.id)}" aria-label="View ${esc(e.title)}"><div class="cardvisual"><img class="${e.source==='USC SCA screenings'?'poster-image':e.source==='Handshake'?'original-source-image':''}" src="${esc(e.image||fallbackImage(e.type))}" alt="" loading="lazy" referrerpolicy="no-referrer" data-fallback="${esc(e.type)}"><span class="type ${e.type.split(' ')[0]}">${icons[e.type]||'◈'} &nbsp;${esc(e.type)}</span>${eligibilityDecision(e,profile).status==='closed'?'<span class="freetag closedtag">Registration closed</span>':e.restricted?'<span class="freetag">🔒 Restricted</span>':e.free?'<span class="freetag">Free admission</span>':''}</div><div class="cardbody"><div class="cardmeta">${uiIcon('clock')}${date(e.start,{weekday:'short'})}${e.end&&dayKey(e.end)!==dayKey(e.start)?' – '+date(e.end):''} <span>·</span> ${e.allDay?'All day':time(e.start)}</div><h3>${esc(e.title)}</h3>${e.occurrences?.length>1?`<span class="series-chip">${uiIcon('calendar')}${e.occurrences.length} dates · view series</span>`:''}<div class="place">${uiIcon('pin')}<span>${esc(e.location)}</span></div><div class="host">${uiIcon('people')}<span>${esc(e.host)}</span></div>${e.source==='Instagram'?`<div class="instagram-origin">Instagram · @${esc(e.sourceAccount||'USC club')}</div>`:''}${audienceMarkup(e,recommended)}${eventConflict(e,busyEntries())?'<span class="conflict-badge">Schedule conflict</span>':''}${filters.sort==='nearest'&&Number.isFinite(distanceMeters(originCoord(),coordinates(e,CAMPUS_PLACES)))?`<span class="distance-badge">~${Math.round(distanceMeters(originCoord(),coordinates(e,CAMPUS_PLACES))/10)*10} m away</span>`:''}</div>${recommended?`<div class="why">${uiIcon('spark')}<div><strong>${aiPicks.key===recommendationKey()&&aiPicks.matchTypes?.[e.id]==='discovery'?'Broaden your radar':aiPicks.key===recommendationKey()&&aiPicks.matchTypes?.[e.id]==='related'?'A related direction':'Why this is for you'}</strong>${esc(why(e))}</div></div>`:''}</button>`}
function setPage(p){if(page==='preferences'&&p!=='preferences'){capturePreferences();if(prefsDraft){profile={...profile,...prefsDraft};save('radar-profile',profile)}}if(p==='ask'){toggleAsk(true);return}const calendarJump=p==='calendar';if(calendarJump)p='login';if(p==='preferences'&&page!=='preferences')prefsDraft=null;page=PAGES.includes(p)?p:'foryou';accountOpen=false;if(['post','posts'].includes(page)&&mode!=='organizer'){mode='organizer';save('radar-mode',mode)}history.replaceState(null,'','#'+page);render();window.scrollTo({top:0,behavior:'instant'});if(page==='login')refreshGoogleStatus();if(calendarJump)$('#calendar-section')?.scrollIntoView({behavior:'smooth',block:'start'});}
function render(){
 destroyLiveMap();
 const nav=mode==='organizer'?[['post','Post an event'],['posts','My event pool'],['foryou','Preview student feed']]:[['foryou','For you'],['browse','Explore events'],['map','Campus map']];
 $('#mainNav').innerHTML=nav.map(([p,l])=>`<button data-page="${p}" class="${page===p?'active':''}">${uiIcon(p==='foryou'?'spark':p==='map'?'pin':p==='browse'?'search':'calendar')}${l}</button>`).join('');$('#participantMode').setAttribute('aria-pressed',String(mode==='participant'));$('#organizerMode').setAttribute('aria-pressed',String(mode==='organizer'));$('#workspaceLabel').textContent=mode==='organizer'?'Organizer studio':'Discover';
 $('#pageLabel').textContent=({foryou:'For you',browse:'Explore events',map:'Campus map',calendar:'Account & calendar',login:'Account & calendar',preferences:'My preferences',post:'Post an event',posts:'My event pool'})[page];
 const content=(!feedReady&&['browse','map'].includes(page))?'<div class="loading"><span>⌖</span>Finding your next campus moment…</div>':({foryou:home,browse:browse,map:map,calendar:loginPage,login:loginPage,preferences:preferencesPage,post:postPage,posts:myPosts})[page]();$('#main').innerHTML=`<div class="pageanimate">${content}</div>`;renderAccount();bind();renderAskPanel();if(page==='map'&&feedReady)initCampusMap();if(page==='foryou'&&feedReady)queueMicrotask(refreshAIRecommendations);
}
function selectedDates(){if(filters.window==='today')return {start:dayKey(now()),end:dayKey(now())};if(filters.window==='week')return {start:dayKey(now()),end:dayKey(now()+6*86400000)};return {start:filters.startDate||'',end:filters.endDate||''}}

function filterToolbar(){const dates=selectedDates();return `<section class="simple-controls" aria-label="Event dates and sorting"><div class="date-range"><label>From<input type="date" id="rangeStart" aria-label="Events from date" value="${dates.start}"></label><span class="date-arrow">→</span><label>To<input type="date" id="rangeEnd" aria-label="Events through date" min="${dates.start}" value="${dates.end}"></label><button class="textlink" id="clearDates">Any dates</button></div><label class="sort-control">Sort by<select data-setting="sort" aria-label="Sort events">${options([['recommended','Recommended for me'],['soonest','Soonest first'],['nearest','Nearest first'],['freefirst','Free admission first'],['shortest','Shortest events first'],['newest','Newest listings'],['onlinefirst','Online events first'],['title','Title · A–Z']],filters.sort)}</select></label><label class="sort-control">Admission<select data-setting="admission">${options([['all','Any admission'],['free','Free admission']],filters.admission)}</select></label><label class="sort-control">Format<select data-setting="format">${options([['all','Any format'],['inperson','In person'],['online','Online']],filters.format)}</select></label><label class="sort-control">Extras<select data-setting="perk">${options([['all','Any extras'],['food','Free food confirmed'],['samples','Free samples confirmed']],filters.perk||'all')}</select></label><label class="conflict-control"><input id="feedConflicts" type="checkbox" ${filters.availability==='available'?'checked':''}>Avoid my calendar conflicts</label>${filters.sort==='nearest'?`<label class="sort-origin">Distance from<select data-setting="origin" aria-label="Distance starting point">${options(CAMPUS_PLACES.map(p=>[p.name,p.name]),filters.origin)}</select></label><small class="distance-note">Straight-line estimates; unknown locations appear last.</small>`:''}</section>`}
function groupSection(list,key,title,subtitle){return `<section class="event-section"><div class="sectiontop"><div><span class="section-kicker">${key==='social'?'LIFE BEYOND THE CLASSROOM':'YOUR NEXT CHAPTER'}</span><h2>${title}</h2><p>${subtitle}</p></div><button class="textlink" data-category-link="${key}">Explore all ↗</button></div>${list.length<5?`<p class="filter-note">${list.length} eligible ${list.length===1?'event':'events'} on these dates. A section shows five whenever enough eligible events are available.</p>`:''}<div class="cards">${list.slice(0,5).map(e=>card(e,true)).join('')||'<div class="empty">No confirmed-eligible events are available in this section on these dates. Try a wider date range.</div>'}</div></section>`}

function recommendationProfile(){return {school:profile.school,year:profile.year,graduationYear:profile.graduationYear,ageBand:profile.ageBand,careerGoal:preferenceContext(profile,'career').goal,careerInterests:preferenceContext(profile,'career').interests,socialGoal:preferenceContext(profile,'social').goal,socialInterests:preferenceContext(profile,'social').interests,careerDocuments:Object.fromEntries(Object.entries(profile.careerDocuments||{}).map(([k,v])=>[k,{text:profileTopics(v?.text||'').join(', ')}]))}}
function recommendationCandidateIds(){return filtered(visible(),{category:'all',type:'All',query:''}).map(e=>e.id)}
function recommendationKey(){return JSON.stringify([recommendationProfile(),selectedDates(),recommendationCandidateIds()])}
async function refreshAIRecommendations(){if(!feedReady||page!=='foryou')return;const key=recommendationKey();if(aiPicks.key===key)return;const serial=++aiRequestNumber;aiPicks={key,state:'loading',career:[],social:[],reasons:{}};const status=$('#recommendationStatus');if(status)status.textContent='Updating recommendations for your preferences…';try{const dates=selectedDates();const result=await request('/api/recommend',{profile:recommendationProfile(),startDate:dates.start,endDate:dates.end,candidateIds:recommendationCandidateIds()});if(serial!==aiRequestNumber||key!==recommendationKey())return;aiPicks={...result,key,state:result.engine==='ai'?'ai':'rules'};}catch{if(serial!==aiRequestNumber)return;aiPicks={key,state:'error',career:[],social:[],reasons:{},message:'AI is temporarily unavailable. Showing interest-matched results.'}}if(page==='foryou')render()}

function recommendationCoverage(){const c=aiPicks.key===recommendationKey()?aiPicks.counts:null;if(!c)return '';return `<details class="filter-note"><summary>How these picks were selected</summary><p>${c.pool} listings in the current pool. ${c.eligibleOnDates} meet your dates, filters and announced eligibility. The matching service considered ${c.careerCandidates} career and ${c.socialCandidates} campus-life candidates, ranked using your active preferences.</p><p>Interest tags and free-text preferences are combined only when you select Use both. Missing or unconfirmed eligibility can reduce the results.</p></details>`}
function home(){const list=filtered(visible(),{category:'all',type:'All',query:''});let career=recommendEvents(list,profile,{category:'career',score,sort:filters.sort,origin:originCoord(),places:CAMPUS_PLACES,limit:5}),social=recommendEvents(list,profile,{category:'social',score,sort:filters.sort,origin:originCoord(),places:CAMPUS_PLACES,limit:5});if(['ai','rules'].includes(aiPicks.state)&&aiPicks.key===recommendationKey()){const lookup=new Map(list.map(e=>[e.id,e]));career=aiPicks.career.map(id=>lookup.get(id)).filter(Boolean).slice(0,5);social=aiPicks.social.map(id=>lookup.get(id)).filter(Boolean).slice(0,5)}return `<section class="welcome-hero"><div class="welcome-copy"><span class="eyebrow">YOUR CAMPUS. YOUR PEOPLE. YOUR NEXT CHAPTER.</span><p class="welcome-greeting">A little more USC. A little more you.</p><h1>Your next<br><em>“glad I went.”</em></h1><p class="welcome-description">The big ideas. The unexpected connections.<br>The little campus moments that become your favorites.</p><div class="welcome-actions"><button class="primary" id="seeWeeklyPicks">Find my next good thing <span>↓</span></button><button class="textlink" data-page="map">See campus live ↗</button></div><span class="welcome-signoff">DISCOVER WHAT BRINGS US TOGETHER.</span></div><div class="welcome-photo"><img src="/assets/fight-on-campus.jpg" alt="USC students in cardinal and gold celebrating together with raised Fight On victory signs" fetchpriority="high"><div class="photo-caption"><span>THE BEST PART OF USC?</span><strong>Being part of it.</strong></div></div></section><section class="picks-intro" id="weeklyPicks"><div><span class="eyebrow">${uiIcon('spark')} YOUR PERSONAL EVENT RADAR</span><h2>${profile.name?esc(profile.name)+', your':'Your'} kind of week.</h2><p>Picked for your interests, checked against your student details.</p></div><div class="week-scope" aria-label="Recommendation time range"><button data-window="week" class="${filters.window==='week'?'selected':''}">This week</button><button data-window="today" class="${filters.window==='today'?'selected':''}">Today</button></div></section>${feedReady?filterToolbar():''}<p class="filter-note" id="recommendationStatus" role="status">${aiPicks.state==='ai'&&aiPicks.key===recommendationKey()?'AI recommendations · matched to your saved interests':aiPicks.state==='loading'?'Updating recommendations for your preferences…':esc(aiPicks.message||'Matching your saved interests…')}</p>${recommendationCoverage()}<div class="home-feed">${feedReady?groupSection(career,'career','Career & growth','Connections, skills, and ideas for your next chapter.')+groupSection(social,'social','Social & campus life','SCA screenings, music, culture, and a little time for yourself.'):'<div class="loading recommendation-loading">Finding eligible events for your week…</div>'}</div>`}
function categoryTypes(){return ['All',...(category==='career'?CAREER_TYPES:category==='social'?SOCIAL_TYPES:[...CAREER_TYPES,...SOCIAL_TYPES])]}
function browse(){const matches=filtered(events),list=groupEventSeries(matches);return `<h1 class="subheading">Follow your curiosity.</h1><p class="pageintro">Explore everything, on the dates that work for you.</p><div class="category-tabs" aria-label="Event sections">${[['all','All events'],['career','Career & growth'],['social','Social & campus life']].map(([v,l])=>`<button class="${category===v?'selected':''}" data-category="${v}" aria-pressed="${category===v}">${l}</button>`).join('')}</div><input class="searchbar" id="eventSearch" placeholder="Search events, topics, organizers, or sources…" aria-label="Search events" value="${esc(query)}">${filterToolbar()}<p class="taxonomy-note">Choose one activity type · counts show distinct activity series over the next 90 days. Repeat dates share one card.</p><div class="chips category-chips">${categoryTypes().map(t=>`<button class="chip ${filter===t?'selected':''}" data-filter="${t}">${esc(t)} <span class=tag-count>${groupEventSeries(events.filter(e=>eventEnd(e)>now()&&Date.parse(e.start)<now()+90*86400000&&(category==='all'||eventCategory(e)===category)&&(t==='All'||eventPrimaryType(e)===t))).length}</span></button>`).join('')}</div><div class="resultsline" id="resultCount">${list.length} ${list.length===1?'activity':'activities'}${matches.length!==list.length?' · '+matches.length+' dates':''}</div><div class="cards browsegrid" id="browseCards">${list.map(e=>card(e)).join('')||'<div class="empty">No matches. Try a wider date range or a different type of event.</div>'}</div>`}

function toggleAsk(force){askOpen=force??!askOpen;$('#askFloat').setAttribute('aria-expanded',String(askOpen));$('#askPanel').hidden=!askOpen;renderAskPanel();if(askOpen){positionAskPanel();$('#askInput')?.focus();}}
function renderAskPanel(){const panel=$('#askPanel');panel.hidden=!askOpen;if(!askOpen)return;panel.innerHTML=`<div class="ask-panel-head"><div><span>✦</span><strong>Ask USC</strong><small>A little direction. A lot to discover.</small></div><button id="closeAsk" aria-label="Close Ask USC">×</button></div><div class="ask-content" aria-live="polite">${chatAnswer?`<div class="chat-question">${esc(chatQuery)}</div><p class="chat-answer">${esc(chatAnswer)}</p><div class="chat-events">${chatResults.map(e=>`<button data-chat-event="${esc(e.id)}"><span class="chat-event-type">${esc(e.type)}</span><strong>${esc(e.title)}</strong><small>${date(e.start)} · ${time(e.start)} · ${esc(e.location)}</small><span class="chat-event-arrow">↗</span></button>`).join('')}</div>`:`<h2>What sounds good today?</h2><p>Tell me what you’re in the mood for. I’ll look through real USC events for you.</p><div class="ask-suggestions">${['Which events have free food?','Where can I find free samples?','Which talks fit my interests this week?','Any hackathons this weekend?'].map(t=>`<button data-ask="${t}">${t} ↗</button>`).join('')}</div>`}${isLoading?'<p class="chat-thinking">Looking for something you’ll love…</p>':''}</div><form id="chatForm" class="floating-chatbox"><input id="askInput" name="question" aria-label="Ask USC a question" placeholder="What would you like to do?" required maxlength="500"><button aria-label="Find events" ${isLoading?'disabled':''}>↗</button></form>`;$('#closeAsk').onclick=()=>toggleAsk(false);$('#chatForm').onsubmit=e=>{e.preventDefault();runAsk(new FormData(e.target).get('question'))};panel.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>runAsk(b.dataset.ask));panel.querySelectorAll('[data-chat-event]').forEach(b=>b.onclick=()=>openEvent(b.dataset.chatEvent));}

const buildings=[{code:'GIN',name:'Ginsburg',re:/ginsburg/i,x:66,y:75},{code:'TCC',name:'Campus Center',re:/TCC|campus center|tommy/i,x:46,y:68},{code:'JFF',name:'Fertitta',re:/JFF|fertitta/i,x:72,y:84},{code:'STU',name:'Student Union',re:/STU|student union|sustainability hub/i,x:48,y:49},{code:'SCA',name:'Cinematic Arts',re:/SCA|cinematic/i,x:29,y:27},{code:'DML',name:'Doheny',re:/DML|doheny/i,x:67,y:36},{code:'ANN',name:'Annenberg',re:/ANN|annenberg/i,x:28,y:55},{code:'MUS',name:'Music',re:/MUS|macdonald/i,x:47,y:19}];
let mapSelected='',mapMode='live',mapQuery='',mapCheckedAt=new Date(),mapSearchTimer;
function currentMapEvents(){return mapCandidates(events,{mode:mapMode,query:mapQuery,places:CAMPUS_PLACES})}
function mapListMarkup(list){return list.map(e=>`<article class="map-event ${mapSelected===e.id?'selected':''}" data-map-row="${esc(e.id)}">${e.image?`<img class="map-thumb" src="${esc(e.image)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}<div><span class="map-event-status ${e.isLive?'now':''}">${e.isLive?'● HAPPENING NOW':'UPCOMING'} · ${date(e.start)}</span><button class="mapitem" data-map-event="${esc(e.id)}"><strong>${esc(e.title)}</strong><small>${time(e.start)}${e.end?' – '+time(e.end):''} · ${esc(e.location)}</small></button><div class="map-item-links">${e.mapPoint?`<button class="textlink" data-map-event="${esc(e.id)}">Locate on map ↗</button>`:'<small>Exact location not publicly available</small>'}<button class="textlink" data-event="${esc(e.id)}">Details ↗</button></div></div></article>`).join('')||`<div class="map-empty"><strong>${mapQuery?'No matching events.':'A quiet moment on campus.'}</strong><p>${mapQuery?'Try another event name, organizer, or location.':'No events with verified public coordinates are confirmed right now. Explore upcoming events for your next stop.'}</p><button class="textlink" data-map-mode="upcoming">Browse upcoming events ↗</button></div>`}
function map(){const list=currentMapEvents(),mapped=list.filter(e=>e.mapPoint);return `<div class="live-map-heading"><div><span class="eyebrow">RIGHT HERE. RIGHT NOW.</span><h1 class="subheading">Campus, happening.</h1><p class="pageintro">Find an event. Follow the red dot. Be part of it.</p></div><div class="map-live-badge"><span></span>Event radar <small>Checked ${time(mapCheckedAt)}</small></div></div><div class="live-map-search"><span aria-hidden="true">⌕</span><input id="mapSearch" type="search" placeholder="Search events, organizers, or places…" aria-label="Search events on map" value="${esc(mapQuery)}"><button class="textlink" id="clearMapSearch">Clear</button></div><div class="live-map-toolbar"><div class="map-view-tabs" aria-label="Map event time"><button data-map-mode="live" aria-pressed="${mapMode==='live'}">Happening now</button><button data-map-mode="upcoming" aria-pressed="${mapMode==='upcoming'}">Upcoming · 90 days</button></div><div class="map-key"><span><i class="key-live"></i> Happening now</span><span><i class="key-upcoming"></i> Upcoming</span></div><button id="refreshMap" class="textlink">Refresh ↻</button></div><div class="radar-map-shell"><div class="radar-map-stage"><div id="liveCampusMap" role="region" aria-label="Interactive campus event map"></div><div class="map-count-pill" id="mapCount">${mapped.length} events · ${groupMapLocations(mapped).length} locations</div><div class="map-provider-bar"><span id="mapProvider">Loading map…</span><a href="https://www.google.com/maps/search/?api=1&query=University+of+Southern+California" target="_blank" rel="noopener" id="openGoogleLocation">Open Google Maps ↗</a></div></div><aside class="radar-map-results"><div class="map-results-heading"><span id="mapResultLabel">${mapQuery?'SEARCH RESULTS · NEXT 90 DAYS':mapMode==='live'?'HAPPENING NOW':'UPCOMING EVENTS'}</span><strong id="mapResultCount">${list.length}</strong></div><section id="mapList" class="radar-map-list" aria-live="polite">${mapListMarkup(list)}</section></aside></div><p class="map-trust-note">Solid red dots show events confirmed in progress. Hollow dots show upcoming events. Events at the same place share a pin. Private or unverified locations stay in the list. Refreshes every minute; source updates may take up to five minutes.</p>`}
function selectMapEvent(id,details=false){if(details)return openEvent(id);mapSelected=id;document.querySelectorAll('[data-map-row]').forEach(el=>el.classList.toggle('selected',el.dataset.mapRow===id));const e=events.find(e=>e.id===id),link=$('#openGoogleLocation');if(e&&link)link.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(e.location+', University of Southern California, Los Angeles')}
function bindMapList(){document.querySelectorAll('[data-map-event]').forEach(b=>b.onclick=()=>{selectMapEvent(b.dataset.mapEvent);initCampusMap()});$('#mapList')?.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>openEvent(b.dataset.event));document.querySelectorAll('[data-map-mode]').forEach(b=>b.onclick=()=>{mapMode=b.dataset.mapMode;mapQuery='';mapSelected='';render()})}
async function initCampusMap(){const container=$('#liveCampusMap');if(!container)return;const list=currentMapEvents();await mountLiveMap(container,list,{selected:mapSelected,key:appConfig.googleMapsKey||'',onSelect:selectMapEvent,onProvider:name=>{if($('#mapProvider'))$('#mapProvider').textContent=name==='Google Maps'?'Google Maps · Live event layer':'OpenStreetMap · Live event layer'}}).catch(()=>{if(container.isConnected)container.innerHTML='<p class="map-load-error">The map could not load. You can still search the event list and open Google Maps.</p>'})}
function updateMapSearch(){const list=currentMapEvents(),mapped=list.filter(e=>e.mapPoint);$('#mapList').innerHTML=mapListMarkup(list);$('#mapResultLabel').textContent=mapQuery?'SEARCH RESULTS · NEXT 90 DAYS':mapMode==='live'?'HAPPENING NOW':'UPCOMING EVENTS';$('#mapResultCount').textContent=list.length;$('#mapCount').textContent=mapped.length+' events · '+groupMapLocations(mapped).length+' locations';bindMapList();initCampusMap()}
function organizationTrustPanel(){return `<section class="org-trust-panel"><div class="org-trust-summary"><div><span class="eyebrow">TRUST BUILT IN</span><h2>Verify once. Share in seconds.</h2><p>Save a poster or email now. Publishing requires a verified representative and checked event details.</p></div><span class="review-pill">${organizationClaim?'Application saved · awaiting review':'Verification required to publish'}</span></div><details id="organizationClaimDetails"><summary>${organizationClaim?'View your verification request':'Verify your organization'} <span>→</span></summary>${organizationClaim?`<div class="claim-receipt"><strong>Request received</strong><p>${esc(organizationClaim.organization)} · ${esc(organizationClaim.typeLabel)}</p><p>Identity, representative authority and evidence still need review. This receipt does not enable publishing.</p><small>Reference: ${esc(organizationClaim.id)}</small><button class="textlink" id="newOrganizationClaim">Submit for another organization</button></div>`:`<form id="organizationClaimForm" class="claim-form"><label>Organizer type<select id="claimType" name="type">${ORGANIZER_TYPES.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label>Organization name<input name="organization" required maxlength="200" autocomplete="organization"></label><label>Organization / work email<input name="email" type="email" required maxlength="254" autocomplete="email"></label><label>Official website or directory profile<input name="proofURL" type="url" placeholder="https://" required maxlength="2000"></label><label class="claim-full">Your role and how we can confirm it<textarea name="role" required maxlength="1200" placeholder="For example: current club officer listed in the directory, department staff member, or authorized brand representative."></textarea></label><p id="claimTypeHelp" class="claim-full">We check the current organization listing and confirm that you are authorized to post. A USC email address alone does not prove club officer authority.</p><button class="primary" type="submit">Request verification <span>→</span></button><small>Saved for review. Email ownership checks and organization approval are not automatic in this preview.</small></form>`}</details><div class="trust-checkpoints"><span>${uiIcon('people')}Representative identity</span><span>${uiIcon('check')}Event source & details</span><span>${uiIcon('pin')}Venue / host confirmation</span></div></section>`}
function postPage(){return `<section class="post-heading"><span class="eyebrow">GOOD THINGS DESERVE A CROWD</span><h1 class="subheading">Bring your event. We’ll handle the details.</h1><p class="pageintro">A poster, a screenshot, or the email you already wrote. Start with what you have.</p></section>${organizationTrustPanel()}<div class="post-method-tabs" role="tablist" aria-label="Event input method"><button role="tab" aria-selected="${postInputMode==='poster'}" data-post-mode="poster">Poster / screenshot</button><button role="tab" aria-selected="${postInputMode==='email'}" data-post-mode="email">Paste an email</button></div><section class="poster-composer">${postInputMode==='poster'?`<div id="posterDrop" class="poster-drop ${selectedPoster?'has-poster':''}" tabindex="0" aria-label="Paste or drop an event poster">${selectedPoster?`<img src="${esc(posterPreview)}" alt="Selected event poster preview"><div><strong>${esc(selectedPoster.name)}</strong><button class="textlink" id="removePoster">Choose another image</button></div>`:`<span class="poster-upload-icon">↑</span><h2>Drop your event poster here.</h2><p>Or paste a screenshot with ⌘V / Ctrl+V.</p><label class="primary" for="posterFile">Choose an image ↗</label><small>PNG, JPG or WebP · up to 4 MB</small>`}</div><input class="sr-only" id="posterFile" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Upload event poster"><button class="primary intake-submit" id="submitPoster" ${!selectedPoster||uploadBusy?'disabled':''}>${uploadBusy?'Adding to your event pool…':'Add poster to event pool'} <span>→</span></button>`:`<form id="emailIntakeForm"><label for="eventEmail" class="sr-only">Event announcement email</label><textarea id="eventEmail" name="text" placeholder="Paste your event email or newsletter here. No need to retype the details." maxlength="16000" required>${esc(pastedEventEmail)}</textarea><button class="primary intake-submit" type="submit">Add email to event pool <span>→</span></button></form>`}<p class="intake-review-note">Submissions are saved for extraction and organizer review before they reach students. No long form to fill out.</p></section><section class="email-cc-card"><div><span class="section-kicker">ALREADY SENDING THE ANNOUNCEMENT?</span><h2>Just CC us.</h2><p>Keep your usual mailing list. Add our event inbox when email intake is activated.</p></div><div><strong>${esc(appConfig.intakeEmail)}</strong><span class="intake-state">${appConfig.intakeActive?'Email intake active':'Proposed inbox · not active yet'}</span><button id="copyIntake" class="textlink">Copy address ↗</button></div></section><section class="other-intake"><span class="eyebrow">OTHER WAYS · IN DEVELOPMENT</span><div>${[['Handshake','Direct organizer event intake'],['EngageSC','Direct organization connection'],['Instagram','Authorized club event posts']].map(([name,desc])=>`<article><strong>${name}</strong><p>${desc}</p><small>In development</small></article>`).join('')}</div></section>${organizerFAQ()}`}
function myPosts(){return `<h1 class="subheading">Your event pool.</h1><p class="pageintro">Your posters and announcements, ready for the next step.</p>${posts.length?posts.map(p=>`<section class="sourcecard" style="margin-bottom:15px"><div class="sourcecardhead"><h3>${esc(p.title)}</h3><span class="status pending">Awaiting review</span></div><small>${p.kind==='poster'?'Poster received':p.kind==='email'?'Email received':'Event received'} · ${date(p.createdAt)} · Not published yet</small></section>`).join(''):'<div class="empty">No events in your pool yet.<br><button class="textlink" data-page="post">Add a poster or email →</button></div>'}`}

function openEvent(id){const e=events.find(e=>e.id===id);if(!e)return;const occurrences=events.filter(o=>seriesKey(o)===seriesKey(e)&&eventEnd(o)>now()).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start));$('#modal').innerHTML=`<button class="close" aria-label="Close dialog">×</button><img class="modalimage" src="${esc(e.image||fallbackImage(e.type))}" alt="" referrerpolicy="no-referrer" data-fallback="${esc(e.type)}"><div class="modalbody"><span class="type ${e.type.split(' ')[0]}">${icons[e.type]} ${esc(e.type)}</span><h2>${esc(e.title)}</h2><div class="detailmeta">◷ &nbsp;${date(e.start,{weekday:'long',year:'numeric'})} · ${e.allDay?'All day':time(e.start)}${e.end&&!e.allDay?' – '+time(e.end):''} PT<br>⌖ &nbsp;${esc(e.location)}<br>♧ &nbsp;${esc(e.host)}<br>↗ &nbsp;${esc(e.eligibility)}${e.free?'<br>Free admission':''}</div>${occurrences.length>1?`<section class="series-dates"><strong>Dates in this series</strong><div>${occurrences.map(o=>`<button data-occurrence="${esc(o.id)}" class="${o.id===e.id?'selected':''}">${date(o.start)} · ${time(o.start)}</button>`).join('')}</div></section>`:''}${audienceMarkup(e)}${e.attendance?.proof?`<p class="eligibility-proof"><strong>From the original listing</strong>${esc(e.attendance.proof)}</p>`:''}${e.warning?`<p class="notice">${esc(e.warning)}</p>`:''}<p>${esc(e.description)}</p><div class="sourceproof">${esc(e.source)} · ${e.importedAt?'Imported '+date(e.importedAt):'Public source feed'}<br>Original: ${esc(new URL(e.url).hostname)}<br>${e.imageCredit?esc(e.imageCredit)+'<br>':''}Registration and eligibility are confirmed on the original platform.</div><div class="modalactions">${e.restricted?'<span class="notice">Your Handshake account is not eligible.</span>':`<a class="primary" target="_blank" rel="noopener noreferrer" href="${esc(e.register||e.url)}">${e.source==='USC email'?'Open original email':eligibilityDecision(e,profile).eligible?'View & register':'View original listing'} <span>↗</span></a>`}<button class="dismiss" id="notForMe">Not for me</button></div></div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').querySelectorAll('[data-occurrence]').forEach(b=>b.onclick=()=>openEvent(b.dataset.occurrence));bindImages();$('#modal .close').onclick=()=>$('#modal').close();$('#notForMe').onclick=()=>{hidden.push(e.id);save('radar-hidden',hidden);$('#modal').close();render();notify('Removed from your picks. You can still find it in Explore.')};}
function editProfile(){prefsDraft=null;setPage('preferences')}
function loginPage(){return `<section class="account-page-heading"><span class="eyebrow">OPTIONAL CONNECTIONS, USEFUL WHEN YOU NEED THEM</span><h1 class="subheading">Your account & calendar.</h1><p class="pageintro">Browsing events doesn’t require a school login. Connect only what helps you.</p></section><section class="identity-card"><div class="identity-profile"><span class="avatar identity-avatar">${avatarMarkup()}</span><div><h2>${esc(profile.name||'Your profile')}</h2><p>Your preferences are saved in this browser.</p></div></div><button class="textlink" data-page="preferences">Edit my preferences ↗</button></section><details class="usc-verification"><summary>USC affiliation verification <span>Not connected</span></summary><p>University verification can confirm USC affiliation and help establish trusted organizer accounts. It does not automatically grant access to your email or calendar.</p><p>Trojan Radar’s USC sign-in integration is not active yet. You can keep using the app as a guest.</p><a class="textlink" href="${esc(appConfig.uscLoginURL)}" target="_blank" rel="noopener noreferrer">Visit the official MyUSC portal ↗</a></details><div id="calendar-section" class="account-calendar-section">${calendarPage()}</div>`}
function capturePreferences(){const form=$('#preferencesForm');if(!form)return;prefsDraft=prefsDraft||{...profile,careerDocuments:{...profile.careerDocuments}};const d=new FormData(form);prefsDraft.name=d.get('name')==='__custom'?(d.get('customName')||'').trim():d.get('name')||'';prefsDraft.school=d.get('school')||'';prefsDraft.year=d.get('year')||'';prefsDraft.graduationYear=d.get('graduationYear')||'';prefsDraft.ageBand=d.get('ageBand')||'';prefsDraft.careerLinkedInURL=d.get('careerLinkedInURL')||'';for(const kind of ['career','social']){prefsDraft[kind+'PreferenceMode']=preferenceModes[kind];if(d.has(kind+'TagsVisible'))prefsDraft[kind+'Interests']=d.getAll(kind+'Interests').join(', ');if(d.has(kind+'Goal'))prefsDraft[kind+'Goal']=d.get(kind+'Goal')||'';}}
function domainPreference(kind,draft){const career=kind==='career',tags=career?CAREER_TAGS:SOCIAL_TAGS,mode=preferenceModes[kind],selected=(draft[kind+'Interests']||'').toLowerCase();return `<section class="domain-preferences"><div class="domain-title"><span>${career?'01':'02'}</span><div><h2>${career?'Career preferences':'Campus life preferences'}</h2><p>${career?'Goals first. Your experience adds a little context.':'The things you do just because you enjoy them.'}</p></div></div>${career?`<div class="career-documents">${[['resume','Resume'],['linkedin','LinkedIn profile PDF']].map(([key,label])=>{const doc=draft.careerDocuments?.[key];return `<div class="profile-document"><label for="${key}File"><span>↑</span><strong>${label}</strong><small>${doc?esc(doc.name):'Choose a PDF or text file · optional'}</small></label><input class="sr-only" id="${key}File" type="file" accept=".pdf,.txt,application/pdf,text/plain" data-career-document="${key}" aria-label="Upload ${label}">${doc?`<p>${profileTopics(doc.text).map(t=>esc(t)).join(' · ')||'Readable text saved'}<button type="button" class="textlink" data-remove-document="${key}">Remove</button></p>`:''}</div>`}).join('')}</div><label for="linkedinURL">LinkedIn profile link <span>optional</span></label><input id="linkedinURL" name="careerLinkedInURL" type="url" placeholder="https://www.linkedin.com/in/…" value="${esc(draft.careerLinkedInURL||'')}"><p class="document-note">PDFs are read in this browser, not uploaded. A LinkedIn link is kept as a reference; upload its Save to PDF export to include experience.</p>`:''}<div class="domain-tabs" role="tablist" aria-label="${career?'Career':'Campus life'} preference method"><button type="button" role="tab" aria-selected="${mode==='tags'}" data-domain-tab="${kind}:tags">Pick from options</button><button type="button" role="tab" aria-selected="${mode==='words'}" data-domain-tab="${kind}:words">In my own words</button><button type="button" role="tab" aria-selected="${mode==='both'}" data-domain-tab="${kind}:both">Use both</button></div><p class="document-note">${mode==='tags'?'Recommendations use your selected tags.':mode==='words'?'Recommendations use what you write below.':'Recommendations use your selected tags and what you write.'}</p>${mode!=='words'?`<input type="hidden" name="${kind}TagsVisible" value="1"><div class="interest-options">${tags.map(([v,l])=>`<label><input type="checkbox" name="${kind}Interests" value="${esc(v)}" ${selected.split(',').map(t=>t.trim()).includes(v.toLowerCase())?'checked':''}><span>${l}</span></label>`).join('')}</div>`:''}${mode!=='tags'?`<label class="sr-only" for="${kind}Goal">${career?'Describe your career interests':'Describe your campus life interests'}</label><textarea id="${kind}Goal" name="${kind}Goal" maxlength="1500" placeholder="${career?'I want to explore AI and marketing, meet people in creative industries, and try a hackathon…':'I’d love SCA screenings, relaxed music nights, free food, and a few ways to meet new people…'}">${esc(draft[kind+'Goal']||'')}</textarea><p class="word-examples">You can be specific, change your mind, or leave this blank.</p>`:''}</section>`}
function preferencesPage(){const draft=prefsDraft||profile,knownName=profile.name||'Student';return `<div class="preferences-header"><span class="eyebrow">OPTIONAL, ALWAYS</span><h1 class="subheading">Make your radar feel like you.</h1><p class="pageintro">One set of preferences for your future. Another for your life outside class. Choose tags, write a few words, or use both.</p></div><form id="preferencesForm" class="preferences-form split-preferences"><details class="basic-profile"><summary>Your student details <span>used to check event eligibility</span></summary><div class="formrow"><div><label for="pname">First name</label><select id="pname" name="name">${options([['','Prefer not to say'],[knownName,knownName],['__custom','Use a different name…']],draft.name&&draft.name!==knownName?'__custom':draft.name||'')}</select><input id="customName" name="customName" placeholder="Your preferred name" aria-label="Different first name" maxlength="50" value="${esc(draft.name&&draft.name!==knownName?draft.name:'')}" ${draft.name&&draft.name!==knownName?'':'hidden'}></div><div><label for="pschool">School</label><select id="pschool" name="school">${options([['','Choose a school'],...SCHOOLS],draft.school||'')}</select></div><div><label for="pyear">Year</label><select id="pyear" name="year">${options([['','Choose your year'],...['Freshman','Sophomore','Junior','Senior','Graduate','Exchange','Alumni','Other'].map(t=>[t,t])],draft.year||'')}</select></div><div><label for="pgraduation">Graduation year</label><select id="pgraduation" name="graduationYear">${options([['','Not specified'],...Array.from({length:12},(_,i)=>[String(2025+i),'Class of '+(2025+i)])],String(draft.graduationYear||''))}</select></div><div><label for="pageBand">Age range · optional</label><select id="pageBand" name="ageBand">${options([['','Not specified'],['Under 18','Under 18'],['18–20','18–20'],['21+','21+']],draft.ageBand||'')}</select></div></div><p class="eligibility-profile-note">School, student year and graduation year are used to check restrictions before recommendations. Age-restricted events stay out of your picks unless your age range is confirmed.</p></details>${domainPreference('career',draft)}${domainPreference('social',draft)}<p id="preferenceSaveStatus" class="filter-note" role="status">Changes to your interests save automatically.</p><div class="preference-actions"><button type="button" class="textlink" data-page="foryou">Skip for now</button><button class="primary" type="submit">Save my preferences <span>→</span></button></div><p class="preference-privacy">Your documents stay in this browser. Interest text and extracted topic labels are sent to the recommendation service. Your resume file and full text are not sent for recommendations. <button type="button" class="textlink" id="resetPersonal">Clear my preferences & feedback</button></p></form>`}

function calendarPage(){const all=busyEntries(),next=all.sort((a,b)=>Date.parse(a.start)-Date.parse(b.start)).filter(e=>Date.parse(e.end)>now()).slice(0,6);return `<div class="calendar-heading"><div><span class="eyebrow">MAKE ROOM FOR THE GOOD THINGS</span><h2 class="subheading">My calendar</h2><p class="pageintro">Find events that fit between the things already in your day.</p>${new URLSearchParams(location.search).has('calendar_error')?'<p class="notice">Google authorization was not completed. Your calendar has not been connected. Try again with your USC account.</p>':''}</div></div><div class="calendar-methods"><section class="calendar-method"><div class="calendar-icon">G</div><span class="section-kicker">CONNECT ONCE</span><h2>USC Google Calendar</h2><p>Connect your USC Google account, choose your calendars, and automatically keep your availability up to date.</p>${googleStatus.connected?`<div class="calendar-connected"><span class="dot"></span>Connected · ${esc(googleStatus.email||'USC Google account')}</div><div class="calendar-choices">${googleCalendars.map(c=>`<label><input type="checkbox" name="googleCalendar" value="${esc(c.id)}" ${googleSelection.includes(c.id)||(!googleSelection.length&&c.primary)?'checked':''}> ${esc(c.name)}</label>`).join('')}</div><button class="primary" id="syncGoogle" ${googleBusy?'disabled':''}>${googleBusy?'Syncing…':'Sync now'} ↻</button><button class="textlink disconnect-calendar" id="disconnectGoogle">Disconnect</button><small>Auto-refreshes while you use Trojan Radar. ${calendarState.googleSyncedAt?'Last synced '+date(calendarState.googleSyncedAt,{hour:'numeric',minute:'2-digit'})+'.':''}</small>`:`<button class="primary" id="connectGoogle">Connect USC Google Calendar ↗</button><small>${googleStatus.configured?'Read-only availability and calendar names. Private event titles and descriptions are not requested.':'Account connection is awaiting Google app setup. File import is available now.'}</small>`}</section><section class="calendar-method"><div class="calendar-icon">↑</div><span class="section-kicker">OR BRING A FILE</span><h2>Import your calendar</h2><p>Upload an .ics export from Google Calendar, Outlook, Apple Calendar, or your course schedule.</p><label class="calendar-upload" for="calendarFile"><span>↑</span><strong>${calendarState.filename?esc(calendarState.filename):'Choose an .ics file'}</strong><small>Up to 1 MB · processed in this browser</small></label><input id="calendarFile" class="sr-only" type="file" accept=".ics,text/calendar"><small>A file is a snapshot. Import it again when your schedule changes.</small>${calendarState.filename?`<button class="textlink" id="clearCalendarFile">Remove imported file</button>`:''}</section></div><section class="calendar-availability"><div><h2>Your time, protected.</h2><p>${all.length?all.length+' busy blocks help shape your recommendations.':'No calendar connected yet. You can still explore every event.'}</p></div><label class="schedule-toggle"><input type="checkbox" id="avoidConflicts" ${filters.availability==='available'?'checked':''}> Avoid conflicts in my recommendations</label></section>${calendarState.skipped?`<p class="notice">${calendarState.skipped} entries had an unsupported date, timezone or recurrence and were not imported. Their times will not be blocked. Weekly and daily repeating schedules are supported.</p>`:''}<section class="calendar-agenda"><div class="sectiontop"><h2>Coming up in your schedule</h2><span class="filter-note">Visible only in this browser</span></div>${next.length?next.map(e=>`<div class="agenda-row"><span class="agenda-date">${date(e.start,{weekday:'short'})}</span><div><strong>${esc(e.title||'Busy')}</strong><small>${e.allDay?'All day':time(e.start)+' – '+time(e.end)} · ${e.source==='google'?'Connected calendar':'Imported file'}</small></div></div>`).join(''):'<div class="empty">Your schedule will appear here when you connect or import a calendar.</div>'}</section><p class="filter-note">Calendar access is read-only. Trojan Radar does not change, create, or delete events in your Google account.</p>`}
function organizerFAQ(){return `<section class="organizer-faq"><span class="eyebrow">GOOD TO KNOW</span><h2>A few quick answers.</h2><details><summary>Can anyone publish an event?</summary><p>Anyone can submit a poster or announcement for review. Public publishing requires checks of the representative, the organization and the event. A submission never becomes a public listing automatically.</p></details><details><summary>Can an outside brand run a free-sample pop-up?</summary><p>Yes. Choose External brand / company when requesting verification. We check business identity and publishing authority, then the event source, exact location and venue/host authorization where required. The listing identifies an external brand; it does not imply USC sponsorship. Free admission, free food and free samples are checked separately.</p></details><details><summary>Does a USC email or an EngageSC link prove someone is a club officer?</summary><p>No. Email ownership, current club recognition, officer authority and event details are separate checks. An official listing supplies source evidence; the representative must still be authorized. AI can extract details and flag inconsistencies, but does not grant a verification badge.</p></details><details><summary>What happens after I add a poster or email?</summary><p>It enters your private event pool for extraction and organizer review. It won’t be published until the event details and organizer have been checked.</p></details><details><summary>Can I CC an email instead of pasting it?</summary><p>Once ${esc(appConfig.intakeEmail)} is activated, CC it on the announcement you already send. The proposed inbox is not receiving mail yet. Pasting an email above works in this preview.</p></details><details><summary>What about Handshake, EngageSC, or another feed?</summary><p>Direct organization connections are in development. Meanwhile, add a screenshot of your announcement or paste its event email. Public USC calendar feeds are handled separately.</p></details></section>`}

async function request(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
async function sync(){try{const [j,c]=await Promise.all([request('/api/events'),request('/api/app-config').catch(()=>appConfig)]);events=j.events;sources=j.sources;appConfig={...appConfig,...c};engine=j.aiAvailable?'AI with grounded event search':'Rules-based matching';feedReady=true;if(page==='preferences')capturePreferences();render()}catch(e){$('#main').innerHTML='<div class="empty">Could not reach the event service. <button class="textlink" id="retry">Try again</button></div>';$('#retry').onclick=sync}}
function questionProfile(q){const {goal,interests}=preferenceContext(profile,/food|samples?|fun|chill|screen|social|relax/i.test(q)?'social':'career');return {goal,interests,school:profile.school,year:profile.year,graduationYear:profile.graduationYear,ageBand:profile.ageBand}}
async function runAsk(q){chatQuery=q.trim();if(!chatQuery||isLoading)return;isLoading=true;askOpen=true;$('#askFloat').setAttribute('aria-expanded','true');renderAskPanel();try{const j=await request('/api/ask',{query:chatQuery,profile:questionProfile(chatQuery)});chatResults=j.ids.map(id=>events.find(e=>e.id===id)).filter(Boolean).filter(e=>eligibilityDecision(e,profile).eligible).filter(e=>filters.availability!=='available'||!eventConflict(e,busyEntries()));chatAnswer=chatResults.length?(j.engine==='ai'?j.answer:`Here are ${chatResults.length} events to explore. These listings match your saved eligibility. RSVP and available places are confirmed by the organizer.`):'No confirmed-eligible events match this request and schedule. Update your school and graduation year in My preferences, or try another interest.'}catch(e){chatAnswer=e.message;chatResults=[]}isLoading=false;renderAskPanel();}
async function refreshGoogleStatus(){try{googleStatus=await request('/api/calendar/google/status');if(googleStatus.connected){const result=await request('/api/calendar/google/calendars');googleCalendars=result.calendars;if(!googleSelection.length)googleSelection=googleCalendars.filter(c=>c.primary).map(c=>c.id);if(!googleBusy)await syncGoogleCalendar(false)}else if(page==='calendar'||page==='login')render()}catch(e){if(page==='calendar'||page==='login')notify('Calendar connection status is unavailable. File import still works.')}}
async function syncGoogleCalendar(announce=true){if(googleBusy||!googleStatus.connected)return;if(!googleSelection.length){if(announce)notify('Choose at least one calendar to sync.');return}googleBusy=true;if(page==='calendar'||page==='login')render();try{const result=await request('/api/calendar/google/sync',{calendarIds:googleSelection});calendarState.googleEntries=result.entries;calendarState.googleSyncedAt=new Date().toISOString();save('radar-calendar',calendarState);if(announce)notify('Calendar synced. Your recommendations now avoid busy times.')}catch(e){if(announce)notify(e.message)}finally{googleBusy=false;if(['calendar','login','foryou','browse'].includes(page))render()}}

function bindImages(){document.querySelectorAll('img[data-fallback]').forEach(img=>img.onerror=()=>{img.onerror=null;img.src=fallbackImage();img.alt='USC campus photo · event artwork unavailable';const cover=img.closest('.cardvisual');if(cover&&!cover.querySelector('.image-origin-note')){const note=document.createElement('span');note.className='image-origin-note';note.textContent='Campus photo · event artwork unavailable';cover.append(note)}})}
function bind(){
 const claimHelp=()=>{const brand=$('#claimType')?.value==='brand';if($('#claimTypeHelp'))$('#claimTypeHelp').textContent=brand?'We confirm your business identity and authority to represent the brand. For campus or managed-property pop-ups, event review also checks venue/host authorization where required. Being near USC does not imply USC sponsorship.':'We check the current organization listing and confirm that you are authorized to post. An email address alone does not prove club officer authority.'};
 if($('#claimType'))$('#claimType').onchange=claimHelp;
 if($('#newOrganizationClaim'))$('#newOrganizationClaim').onclick=()=>{organizationClaim=null;save('radar-organization-claim',null);render();$('#organizationClaimDetails').open=true};
 if($('#organizationClaimForm'))$('#organizationClaimForm').onsubmit=async event=>{event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');button.disabled=true;try{const result=await request('/api/organization-claims',data);organizationClaim={id:result.id,organization:data.organization,typeLabel:ORGANIZER_TYPES.find(([v])=>v===data.type)?.[1]||data.type};save('radar-organization-claim',organizationClaim);render();$('#organizationClaimDetails').open=true;notify('Verification request saved. Publishing remains disabled until review.')}catch(error){notify(error.message);button.disabled=false}};

 document.querySelectorAll('[data-window]').forEach(b=>b.onclick=()=>{filters.window=b.dataset.window;filters.startDate='';filters.endDate='';save('radar-filters',filters);render()});
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>openEvent(b.dataset.event));
 document.querySelectorAll('[data-category-link]').forEach(b=>b.onclick=()=>{category=b.dataset.categoryLink;query='';filter='All';setPage('browse')});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;filter='All';render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});
 document.querySelectorAll('[data-setting]').forEach(el=>el.onchange=()=>{filters[el.dataset.setting]=el.value;save('radar-filters',filters);render()});
 const changeRange=()=>{const start=$('#rangeStart').value,end=$('#rangeEnd').value;if(start&&end&&end<start){notify('Choose an end date on or after the start date.');return}filters.window='custom';filters.startDate=start;filters.endDate=end;save('radar-filters',filters);render()};if($('#rangeStart'))$('#rangeStart').onchange=changeRange;if($('#rangeEnd'))$('#rangeEnd').onchange=changeRange;if($('#clearDates'))$('#clearDates').onclick=()=>{filters.window='custom';filters.startDate='';filters.endDate='';save('radar-filters',filters);render()};
 if($('#feedConflicts'))$('#feedConflicts').onchange=e=>{filters.availability=e.target.checked?'available':'all';save('radar-filters',filters);render()};
 if($('#eventSearch'))$('#eventSearch').oninput=e=>{query=e.target.value;const matches=filtered(events),list=groupEventSeries(matches);$('#browseCards').innerHTML=list.map(x=>card(x)).join('')||'<div class="empty">No matches. Try a broader search.</div>';$('#resultCount').textContent=list.length+(list.length===1?' activity':' activities')+(matches.length!==list.length?' · '+matches.length+' dates':'');$('#browseCards').querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>openEvent(b.dataset.event));bindImages()};
 bindMapList();
 if($('#mapSearch'))$('#mapSearch').oninput=e=>{mapQuery=e.target.value;mapSelected='';clearTimeout(mapSearchTimer);mapSearchTimer=setTimeout(()=>{if(page==='map')updateMapSearch()},220)};
 if($('#clearMapSearch'))$('#clearMapSearch').onclick=()=>{mapQuery='';mapSelected='';$('#mapSearch').value='';updateMapSearch()};
 if($('#refreshMap'))$('#refreshMap').onclick=()=>refreshMapFeed(true);
 if($('#seeWeeklyPicks'))$('#seeWeeklyPicks').onclick=()=>$('#weeklyPicks').scrollIntoView({behavior:'smooth',block:'start'});
 document.querySelectorAll('[data-domain-tab]').forEach(b=>b.onclick=()=>{capturePreferences();const [kind,tab]=b.dataset.domainTab.split(':');preferenceModes[kind]=tab;prefsDraft[kind+'PreferenceMode']=tab;profile={...profile,...prefsDraft};save('radar-profile',profile);render()});
 if($('#pname'))$('#pname').onchange=e=>{$('#customName').hidden=e.target.value!=='__custom';if(!$('#customName').hidden)$('#customName').focus()};
 document.querySelectorAll('[data-career-document]').forEach(el=>el.onchange=async()=>{const file=el.files[0];if(!file)return;capturePreferences();notify('Reading your document privately…');try{const doc=await readProfileDocument(file);if(page!=='preferences')return;prefsDraft.careerDocuments={...prefsDraft.careerDocuments,[el.dataset.careerDocument]:doc};render();notify('Document read. Save your preferences to use its topics.')}catch(e){notify(e.message)}});
 document.querySelectorAll('[data-remove-document]').forEach(b=>b.onclick=()=>{capturePreferences();prefsDraft.careerDocuments={...prefsDraft.careerDocuments};delete prefsDraft.careerDocuments[b.dataset.removeDocument];render()});
 if($('#preferencesForm')){let saveTimer;const autoSave=()=>{capturePreferences();profile={...profile,...prefsDraft};save('radar-profile',profile);renderAccount();const status=$('#preferenceSaveStatus');if(status)status.textContent='Saved · your recommendations will use these preferences.';};$('#preferencesForm').addEventListener('change',e=>{if(e.target.type!=='file')autoSave()});$('#preferencesForm').addEventListener('input',e=>{if(e.target.tagName==='TEXTAREA'){clearTimeout(saveTimer);saveTimer=setTimeout(autoSave,250)}});}
 if($('#preferencesForm'))$('#preferencesForm').onsubmit=e=>{e.preventDefault();capturePreferences();if(prefsDraft.careerLinkedInURL){try{const u=new URL(prefsDraft.careerLinkedInURL);if(u.protocol!=='https:'||!(u.hostname==='linkedin.com'||u.hostname.endsWith('.linkedin.com')))throw Error()}catch{return notify('Use an HTTPS LinkedIn profile link, or leave it blank.')}}profile={...profile,...prefsDraft};save('radar-profile',profile);prefsDraft=null;setPage('foryou');notify('Career and campus life preferences saved separately.')};
 if($('#resetPersonal'))$('#resetPersonal').onclick=()=>{profile={name:'',school:'',year:'',goal:'',interests:'',careerGoal:'',careerInterests:'',socialGoal:'',socialInterests:'',careerDocuments:{},careerLinkedInURL:''};hidden=[];prefsDraft=null;save('radar-profile',profile);save('radar-hidden',hidden);render();notify('Your documents, preferences and feedback were cleared.')};
 if($('#calendarFile'))$('#calendarFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1048576)throw Error('Choose an .ics file smaller than 1 MB.');const result=parseCalendar(await file.text());if(!result.entries.length)throw Error(result.skipped?'No supported upcoming events could be imported.':'No busy blocks were found in the next six months.');calendarState={...calendarState,...result,filename:file.name,importedAt:new Date().toISOString()};save('radar-calendar',calendarState);render();notify(`${result.entries.length} busy blocks imported privately.`)}catch(error){notify(error.message)}};
 if($('#clearCalendarFile'))$('#clearCalendarFile').onclick=()=>{calendarState={...calendarState,entries:[],filename:'',skipped:0};save('radar-calendar',calendarState);render();notify('Imported file removed. Your connected calendars are unchanged.')};
 if($('#avoidConflicts'))$('#avoidConflicts').onchange=e=>{filters.availability=e.target.checked?'available':'all';save('radar-filters',filters);notify(e.target.checked?'Recommendations will avoid your busy times.':'Recommendations can include schedule conflicts.')};
 if($('#connectGoogle'))$('#connectGoogle').onclick=()=>{if(!googleStatus.configured)return notify('Google Calendar connection needs app setup. You can import an .ics file now.');location.assign('/api/calendar/google/start')};
 document.querySelectorAll('[name="googleCalendar"]').forEach(el=>el.onchange=()=>{googleSelection=[...document.querySelectorAll('[name="googleCalendar"]:checked')].map(el=>el.value);save('radar-google-selection',googleSelection)});
 if($('#syncGoogle'))$('#syncGoogle').onclick=()=>syncGoogleCalendar();
 if($('#disconnectGoogle'))$('#disconnectGoogle').onclick=async()=>{try{await request('/api/calendar/google/disconnect',{});googleStatus={...googleStatus,connected:false};calendarState.googleEntries=[];calendarState.googleSyncedAt='';googleCalendars=[];googleSelection=[];save('radar-calendar',calendarState);save('radar-google-selection',[]);render();notify('Google Calendar disconnected.')}catch(e){notify(e.message)}};
 if($('#copyIntake'))$('#copyIntake').onclick=async()=>{try{await navigator.clipboard.writeText(appConfig.intakeEmail);notify(appConfig.intakeActive?'Event inbox copied.':'Proposed address copied. The inbox is not active yet.')}catch{notify(appConfig.intakeEmail)}};
 document.querySelectorAll('[data-post-mode]').forEach(b=>b.onclick=()=>{if($('#eventEmail'))pastedEventEmail=$('#eventEmail').value;postInputMode=b.dataset.postMode;render()});
 if($('#posterFile'))$('#posterFile').onchange=e=>{if(e.target.files[0])selectPoster(e.target.files[0])};
 if($('#posterDrop')){const drop=$('#posterDrop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag-over')};drop.ondragleave=()=>drop.classList.remove('drag-over');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag-over');if(e.dataTransfer.files[0])selectPoster(e.dataTransfer.files[0])};drop.onkeydown=e=>{if(e.key==='Enter'&&!selectedPoster)$('#posterFile').click()}};
 if($('#removePoster'))$('#removePoster').onclick=()=>{if(posterPreview)URL.revokeObjectURL(posterPreview);posterPreview='';selectedPoster=null;render();$('#posterFile').click()};
 if($('#submitPoster'))$('#submitPoster').onclick=submitPoster;
 if($('#emailIntakeForm'))$('#emailIntakeForm').onsubmit=async e=>{e.preventDefault();const text=$('#eventEmail').value.trim();if(text.length<20)return notify('Paste the full event announcement.');const btn=e.target.querySelector('[type=submit]');btn.disabled=true;try{const result=await request('/api/text-submissions',{text});posts.unshift(result);save('radar-posts',posts);pastedEventEmail='';setPage('posts');notify('Email added to your private event pool for review.')}catch(e){notify(e.message);btn.disabled=false}};
 bindImages();
}

async function selectPoster(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>4*1024*1024)return notify('Choose a PNG, JPG or WebP smaller than 4 MB.');if(posterPreview)URL.revokeObjectURL(posterPreview);selectedPoster=file;posterPreview=URL.createObjectURL(file);postInputMode='poster';render();}
async function submitPoster(){if(!selectedPoster||uploadBusy)return;uploadBusy=true;render();try{const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(selectedPoster)});const result=await request('/api/poster-submissions',{name:selectedPoster.name.slice(0,200),mime:selectedPoster.type,image});posts.unshift(result);save('radar-posts',posts);URL.revokeObjectURL(posterPreview);posterPreview='';selectedPoster=null;uploadBusy=false;setPage('posts');notify('Poster added to your private event pool. It is not public yet.')}catch(e){uploadBusy=false;render();notify(e.message||'The poster could not be submitted.')}}
function reactMascot(){const b=$('#askFloat');b.classList.remove('mascot-hello');void b.offsetWidth;b.classList.add('mascot-hello');}
let mascotDragged=false;
function positionAskPanel(){if(!askOpen)return;const r=$('#askFloat').getBoundingClientRect(),panel=$('#askPanel');const width=Math.min(420,innerWidth-30),height=Math.min(565,innerHeight-110);panel.style.left=Math.max(15,Math.min(r.left,innerWidth-width-15))+'px';panel.style.bottom='auto';panel.style.top=Math.max(15,Math.min(r.top-height-10,innerHeight-height-15))+'px';panel.style.height=height+'px';}
function setupMascot(){const button=$('#askFloat');const restore=()=>{const stored=load('radar-mascot-position',null);if(stored){button.style.left=Math.max(12,Math.min(stored.x,innerWidth-button.offsetWidth-12))+'px';button.style.top=Math.max(12,Math.min(stored.y,innerHeight-button.offsetHeight-12))+'px';button.style.bottom='auto'}positionAskPanel()};restore();let pointer=null;
 button.onclick=e=>{if(mascotDragged&&e.detail>0){mascotDragged=false;return}reactMascot();toggleAsk()};
 button.onpointerenter=reactMascot;button.addEventListener('animationend',e=>{if(e.animationName==='trojanHello')button.classList.remove('mascot-hello')});button.onpointerdown=e=>{if(e.button!==0)return;reactMascot();const r=button.getBoundingClientRect();pointer={id:e.pointerId,x:e.clientX,y:e.clientY,left:r.left,top:r.top};mascotDragged=false;button.setPointerCapture(e.pointerId)};
 button.onpointermove=e=>{if(!pointer||pointer.id!==e.pointerId)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.hypot(dx,dy)>6)mascotDragged=true;if(!mascotDragged)return;button.classList.add('dragging');button.style.left=Math.max(12,Math.min(pointer.left+dx,innerWidth-button.offsetWidth-12))+'px';button.style.top=Math.max(12,Math.min(pointer.top+dy,innerHeight-button.offsetHeight-12))+'px';button.style.bottom='auto';positionAskPanel()};
 const end=e=>{if(!pointer||pointer.id!==e.pointerId)return;if(mascotDragged){const r=button.getBoundingClientRect();save('radar-mascot-position',{x:r.left,y:r.top})}pointer=null;button.classList.remove('dragging');if(button.hasPointerCapture(e.pointerId))button.releasePointerCapture(e.pointerId)};button.onpointerup=end;button.onpointercancel=end;window.addEventListener('resize',restore);
}
$('#participantMode').onclick=()=>setMode('participant');$('#organizerMode').onclick=()=>setMode('organizer');$('#profileTop').onclick=()=>{accountOpen=!accountOpen;renderAccount()};document.addEventListener('click',e=>{if(accountOpen&&!e.target.closest('.account-wrap')){accountOpen=false;renderAccount()}});setupMascot();
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(accountOpen){accountOpen=false;renderAccount()}if(!$('#modal').open&&askOpen)toggleAsk(false)}});
window.addEventListener('hashchange',()=>setPage(location.hash.slice(1)));
page=PAGES.includes(location.hash.slice(1))?location.hash.slice(1):'foryou';if(page==='calendar')page='login';if(['post','posts'].includes(page))mode='organizer';render();sync().then(refreshGoogleStatus);
setInterval(()=>{if(googleStatus.connected&&!document.hidden&&!googleBusy)syncGoogleCalendar(false)},300000);

document.addEventListener('paste',e=>{if(page!=='post')return;const file=[...(e.clipboardData?.files||[])].find(f=>f.type.startsWith('image/'));if(file){e.preventDefault();selectPoster(file)}});

async function refreshMapFeed(manual=false){try{const j=await request('/api/events');if(Array.isArray(j.events)){events=j.events;mapCheckedAt=new Date();if(page==='map')render();if(manual)notify('Event listings refreshed.')}}catch(e){if(manual)notify('Could not refresh events. Showing the last available listings.')}}
setInterval(()=>{if(page==='map'&&!document.hidden)refreshMapFeed()},60000);
